const response = $input.first().json;
const platforms = response.platforms || response.data || [];

let totalRevenue = 0;
let totalCosts = 0;
let totalFallenLoss = 0;
let totalNet = 0;

let lines = [];

for (const p of platforms) {
  const rev = Number(p.total_revenue || 0);
  const cost = Number(p.total_cost || 0);
  const loss = Number(p.fallen_loss || 0);
  const net = rev - cost - loss;

  totalRevenue += rev;
  totalCosts += cost;
  totalFallenLoss += loss;
  totalNet += net;

  lines.push(`• <b>${p.platform}</b>: Cobrado $${rev.toLocaleString('es-AR')} | Neto: <b>$${net.toLocaleString('es-AR')}</b> (${p.health_indicator || 'OK'})`);
}

const marginPct = totalRevenue > 0 ? ((totalNet / totalRevenue) * 100).toFixed(1) : '0.0';

const msg = 
  `📊 <b>[STREAMVAULT v2 — RESUMEN EJECUTIVO SEMANAL]</b>\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
  `💰 <b>Facturación Total:</b> $${totalRevenue.toLocaleString('es-AR')} ARS\n` +
  `📉 <b>Costos Mayoristas:</b> $${totalCosts.toLocaleString('es-AR')} ARS\n` +
  `⚠️ <b>Pérdidas por Caídas:</b> $${totalFallenLoss.toLocaleString('es-AR')} ARS\n` +
  `🌟 <b>GANANCIA NETA REAL:</b> $${totalNet.toLocaleString('es-AR')} ARS (<b>${marginPct}%</b>)\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
  `<b>Desglose por Plataforma:</b>\n` +
  lines.slice(0, 10).join('\n') + `\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
  `✨ <i>Generado automáticamente por n8n para optimización del negocio.</i>`;

return [{
  json: {
    totalRevenue,
    totalNet,
    marginPct,
    formatted_text: msg
  }
}];
